python - <<'PY'
import numpy as np
import xarray as xr
from xarray.core.missing import decompose_interp

indexes_coords = {
    "x": (
        np.array([0.0, 1.0], dtype=np.float64),
        xr.DataArray(np.zeros((2,), dtype=np.float64), dims=("lat",)),
    ),
    "y": (
        np.array([0.0, 1.0, 2.0], dtype=np.float64),
        xr.DataArray(np.zeros((3, 2), dtype=np.float64), dims=("time", "lat")),
    ),
    "z": (
        np.array([0.0, 1.0], dtype=np.float64),
        xr.DataArray(np.zeros((2,), dtype=np.float64), dims=("depth",)),
    ),
    "w": (
        np.array([0.0, 1.0], dtype=np.float64),
        xr.DataArray(np.zeros((2, 1), dtype=np.float64), dims=("depth", "member")),
    ),
    "v": (
        np.array([0.0, 1.0, 2.0], dtype=np.float64),
        xr.DataArray(np.zeros((3,), dtype=np.float64), dims=("member",)),
    ),
}

dest_dims = [
    dest[1].dims if dest[1].ndim > 0 else (dim,)
    for dim, dest in indexes_coords.items()
]
partial_dest_dims = []
partial_indexes_coords = {}
for i, index_coords in enumerate(indexes_coords.items()):
    partial_indexes_coords.update([index_coords])
    if i == 4:
        print(i, list(partial_indexes_coords.keys()))
        break

    if i == len(dest_dims) - 1:
        break
    partial_dest_dims += [dest_dims[i]]
    other_dims = dest_dims[i + 1 :]
    s_partial_dest_dims = {dim for dims in partial_dest_dims for dim in dims}
    s_other_dims = {dim for dims in other_dims for dim in dims}
    if not s_partial_dest_dims.intersection(s_other_dims):
        partial_dest_dims = []
        partial_indexes_coords = {}
